function lessonTopicIdFor(x){return x.topic_id||lessonTopicIds[x.topic]||null;}
function lessonField(x,key){
  if(isChineseCourse())return x[key];
  const z=translationLanguage==="zh"?lessonZh[x.id]:null;
  return z&&z[key]!==undefined?z[key]:x[key];
}
function lessonPractice(x){
  const z=isEnglishCourse()&&translationLanguage==="zh"?lessonZh[x.id]:null;
  const src=x.practices||[x.practice];
  const translated=z?.practices||(z?.practice?[z.practice]:null);
  const orders=ls.practiceOptionOrders?.[x.id];
  return src.map((q,i)=>{
    const options=translated?.[i]?.options||q.options;
    const order=orders?.[i]||options.map((_,j)=>j);
    return {q:translated?.[i]?.q||q.q,options:order.map(j=>options[j]),answer:order.indexOf(q.answer)};
  });
}
    function shuffleLessonOptionOrders(x){const src=x.practices||[x.practice],previous=ls.lastPracticeOptionOrders?.[x.id]||[];const orders=src.map((q,i)=>{const base=q.options.map((_,j)=>j);let order=base.slice();for(let k=order.length-1;k>0;k--){const j=Math.floor(Math.random()*(k+1));[order[k],order[j]]=[order[j],order[k]];}if(order.length>1&&previous[i]&&order.every((v,j)=>v===previous[i][j])){for(let k=order.length-1;k>0;k--){const j=Math.floor(Math.random()*(k+1));[order[k],order[j]]=[order[j],order[k]];}if(order.every((v,j)=>v===previous[i][j]))order.push(order.shift());}return order;});ls.lastPracticeOptionOrders={...(ls.lastPracticeOptionOrders||{}),[x.id]:orders.map(a=>a.slice())};ls.practiceOptionOrders={...(ls.practiceOptionOrders||{}),[x.id]:orders};}
    const ls={difficulty:"beginner",topic:"all",progress:[],active:null,busy:false,completing:false,practiceOptionOrders:{},lastPracticeOptionOrders:{},practiceFirstTry:[],practiceAttemptCounts:[],practiceLastChecked:[],practiceIncorrectAttemptCount:0,practiceRetryCount:0,allowanceKnown:false,allowanceUnlimited:false,allowanceRemaining:null,allowanceLimit:null};
